This PR fix error for go anon fn variable call (fix #13741).

- Fix error for go anon fn variable call.
- Add test.

```v
fn sum(a int, b int) int {
	// Simply proxy the function into an anonymous function for demo purposes
	sum_func := fn (a int, b int) int {
		return a + b
	}

	// and run it concurrently
	g := go sum_func(a, b)

	result := g.wait()
	return result
}

fn main() {
	ret := sum(22, 33)
	println(ret)
	assert ret == 55
}

PS D:\Test\v\tt1> v run .
55
```

